     3	import { revalidatePath } from "next/cache";
     4	
     5	import { createClient } from "@/utils/supabase/server";
     6	
     7	export async function signup(formData: { email?: string; password?: string; username?: string }) {
     8	  const supabase = await createClient();
     9	  const form_data = {
    10	    email: formData?.email as string,
    11	    password: formData?.password as string,
    12	  };
    13	
    14	  // First check if user already exists
    15	  const { data: existingUser } = await supabase
    16	    .from("User")
    17	    .select("*")
    18	    .eq("email", form_data.email)
    19	    .maybeSingle();
    20	
    21	  if (existingUser) {
    22	    return { error: { message: "An account with this email already exists" } };
    23	  }
    24	
    25	  // Attempt to sign up
    26	  const { error: signupError, data: signupData } = await supabase.auth.signUp(form_data);
    27	  if (signupError) {
    28	    // Format the error message to be more user-friendly
    29	    let errorMessage = signupError.message;
    30	    if (errorMessage.includes("Password should be")) {
    31	      errorMessage = "Password must be at least 6 characters long";
    32	    } else if (errorMessage.includes("Invalid email")) {
    33	      errorMessage = "Please enter a valid email address";
    34	    }
    35	    return { error: { message: errorMessage } };
    36	  }
    37	
    38	  if (!signupData.user) {
    39	    return { error: { message: "Failed to create account" } };
    40	  }
    41	
    42	  try {
    43	    // Get the newly created user
    44	    const { data: dbGetData, error: dbGetError } = await supabase
    45	      .from("User")
    46	      .select()
    47	      .eq("email", form_data.email)
    48	      .maybeSingle();
    49	
    50	    if (dbGetError || !dbGetData) {
    51	      return {
    52	        error: {
    53	          message:
    54	            "Account created but failed to set username. Please try signing in and updating your profile.",
    55	        },
    56	      };
    57	    }
    58	
    59	    // Update the username
    60	    const { error: updateUserError } = await supabase
    61	      .from("User")
    62	      .update({ username: formData?.username as string })
    63	      .eq("id", dbGetData.id);
    64	
    65	    if (updateUserError) {
    66	      return {
    67	        error: {
    68	          message:
    69	            "Account created but failed to set username. Please try signing in and updating your profile.",
    70	        },
    71	      };
    72	    }
    73	
    74	    revalidatePath("/", "layout");
    75	    return { success: true };
    76	  } catch {
    77	    return {
    78	      error: {
    79	        message: "An unexpected error occurred. Please try again.",
    80	      },
