  3	import React, { useCallback, useEffect, useMemo, useState } from "react";
  4	import { ChevronLeft, ChevronRight } from "lucide-react";
  5	import Image from "next/image";
  6	
  7	interface CalendarApiResponse {
  8	  id: number;
  9	  date: string;
 10	  meal_type: string;
 11	  status: boolean | null;
 12	  Recipe: {
 13	    id: number;
 14	    name: string;
 15	    image_url?: string;
 16	    description?: string;
 17	    min_prep_time?: number;
 18	    green_score?: number | string;
 19	  } | null;
 20	}
 21	
 22	interface MealDetailModalProps {
 23	  isOpen: boolean;
 24	  onClose: () => void;
 25	  entries: CalendarApiResponse[] | null;
 26	  onUpdateStatus: (id: number, newStatus: boolean) => Promise<void>;
 27	  reloadEvents: () => Promise<void>;
 28	}
 29	
 30	export default function MealDetailModal({
 31	  isOpen,
 32	  onClose,
 33	  entries,
 34	  onUpdateStatus,
 35	  reloadEvents,
 36	}: MealDetailModalProps) {
 37	  const [busy, setBusy] = useState(false);
 38	  const [selectedIndex, setSelectedIndex] = useState(0);
 39	
 40	  const len = entries?.length ?? 0;
 41	
 42	  useEffect(() => {
 43	    if (len > 0) setSelectedIndex(0);
 44	  }, [len]);
 45	
 46	  const selected = useMemo<CalendarApiResponse | null>(() => {
 47	    if (!entries || len === 0) return null;
 48	    const safeIndex = ((selectedIndex % len) + len) % len;
 49	    return entries[safeIndex];
 50	  }, [entries, len, selectedIndex]);
 51	
 52	  const isPast = useMemo(() => {
 53	    if (!selected) return false;
 54	    const todayStr = new Date().toLocaleDateString("en-CA");
 55	    const lhs = new Date(selected.date);
 56	    const rhs = new Date(todayStr);
 57	    lhs.setHours(0, 0, 0, 0);
 58	    rhs.setHours(0, 0, 0, 0);
 59	    return lhs.getTime() < rhs.getTime();
 60	  }, [selected]);
 61	
 62	  const allCompleted = useMemo(
 63	    () => (entries ? entries.every((e) => e.status === true) : false),
 64	    [entries]
 65	  );
 66	
 67	  const handlePrev = useCallback(() => {
 68	    if (len <= 0) return;
 69	    setSelectedIndex((prev) => (prev > 0 ? prev - 1 : len - 1));
 70	  }, [len]);
 71	
 72	  const handleNext = useCallback(() => {
 73	    if (len <= 0) return;
 74	    setSelectedIndex((prev) => (prev + 1) % len);
 75	  }, [len]);
 76	
 77	  useEffect(() => {
 78	    if (!isOpen) return;
 79	    const onKey = (e: KeyboardEvent) => {
 80	      if (e.key === "ArrowLeft") handlePrev();
 81	      if (e.key === "ArrowRight") handleNext();
 82	    };
 83	    window.addEventListener("keydown", onKey);
 84	    return () => window.removeEventListener("keydown", onKey);
 85	  }, [isOpen, handlePrev, handleNext]);
 86	
 87	  // update one
 88	  const handleSingleUpdate = useCallback(
 89	    async (entryId: number, newStatus: boolean) => {
 90	      if (busy) return;
 91	      try {
 92	        setBusy(true);
 93	        await onUpdateStatus(entryId, newStatus);
 94	        await reloadEvents();
 95	        onClose();
 96	      } finally {
 97	        setBusy(false);
 98	      }
 99	    },
100	    [busy, onUpdateStatus, reloadEvents, onClose]
101	  );
102	
103	  // update all
104	  const handleBulkUpdate = useCallback(
105	    async (newStatus: boolean) => {
106	      if (busy || !entries || len === 0) return;
107	      try {
108	        setBusy(true);
109	        await Promise.all(entries.map((e) => onUpdateStatus(e.id, newStatus)));
110	        await reloadEvents();
111	        onClose();
112	      } finally {
113	        setBusy(false);
114	      }
115	    },
116	    [busy, entries, len, onUpdateStatus, reloadEvents, onClose]
117	  );
118	
119	  if (!isOpen || len === 0 || !selected) return null;
120	
121	  return (
122	    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
123	      <div className="brutalism-card brutalism-shadow-xl relative w-full max-w-2xl rounded-none p-8">
124	        <div className="flex flex-col items-center">
125	          {!!selected.Recipe?.image_url && (
126	            <div className="brutalism-border relative mb-4 h-48 w-full">
127	              <Image
128	                src={selected.Recipe.image_url}
129	                alt={selected.Recipe.name ?? "meal"}
130	                fill
131	                className="rounded-none object-cover"
132	              />
133	            </div>
134	          )}
135	
136	          {/* title and arrow */}
137	          <div className="mb-2 flex w-full items-center justify-between">
138	            <button
139	              onClick={handlePrev}
140	              className={`brutalism-border brutalism-shadow-sm brutalism-hover brutalism-active rounded-none bg-white p-2 ${len <= 1 ? "invisible" : ""}`}
141	              aria-label="Previous meal"
142	            >
143	              <ChevronLeft className="h-6 w-6" />
144	            </button>
145	
146	            <h3 className="brutalism-heading flex-1 truncate px-2 text-center text-2xl capitalize">
147	              {selected.Recipe?.name ?? selected.meal_type}
148	            </h3>
149	
150	            <button
151	              onClick={handleNext}
152	              className={`brutalism-border brutalism-shadow-sm brutalism-hover brutalism-active rounded-none bg-white p-2 ${len <= 1 ? "invisible" : ""}`}
153	              aria-label="Next meal"
154	            >
155	              <ChevronRight className="h-6 w-6" />
156	            </button>
157	          </div>
158	
159	          <p className="mb-4 text-sm text-gray-600">
160	            {selected.meal_type.charAt(0).toUpperCase() + selected.meal_type.slice(1)} on{" "}
161	            {selected.date} ({(selectedIndex % len) + 1}/{len})
162	          </p>
163	
164	          {!!selected.Recipe?.description && (
165	            <p className="mb-6 max-h-40 overflow-y-auto whitespace-pre-line text-gray-700">
166	              {selected.Recipe.description}
167	            </p>
168	          )}
169	
170	          {isPast && (
171	            <p className="mb-2 w-full text-center text-xs font-semibold text-gray-600">
172	              Past meal — status can still be updated.
173	            </p>
174	          )}
175	
176	          {/* status controls */}
177	          {selected.status ? (
178	            <button
179	              onClick={() => handleSingleUpdate(selected.id, false)}
180	              disabled={busy}
181	              className="brutalism-border brutalism-shadow brutalism-hover brutalism-active mb-3 w-full rounded-none bg-yellow-300 px-4 py-2 font-bold disabled:opacity-60"
182	            >
183	              Mark as Incomplete
184	            </button>
185	          ) : (
186	            <button
187	              onClick={() => handleSingleUpdate(selected.id, true)}
188	              disabled={busy}
189	              className="brutalism-button-primary mb-3 w-full rounded-none px-4 py-2 disabled:opacity-60"
190	            >
191	              ✅ Mark as Completed
192	            </button>
193	          )}
194	        </div>
195	
196	        {/* bottom button  */}
197	        <div className="mt-4 flex justify-between gap-3">
198	          <button
199	            onClick={() => handleBulkUpdate(!allCompleted)}
200	            disabled={busy}
201	            className={`brutalism-border brutalism-shadow brutalism-hover brutalism-active rounded-none px-4 py-2 font-bold ${
202	              allCompleted ? "bg-yellow-300" : "bg-emerald-400"
203	            } disabled:opacity-60`}
204	          >
205	            {allCompleted ? "Mark All as Incomplete" : "✅ Mark All as Completed"}
206	          </button>
207	
208	          <button
209	            onClick={onClose}
210	            disabled={busy}
211	            className="brutalism-button-neutral rounded-none px-4 py-2 disabled:opacity-60"
212	          >
213	            Close
214	          </button>
215	        </div>
216	      </div>
217	    </div>
218	  );
219	}

